import {categories,accounts,today,money,cents,validate,summary,opening,sign,mergeImport} from './core.mjs';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const key='cofre-gabriel-v1';let entries=[],page='overview',search='',typeFilter='',statusFilter='',pendingImport=null;let storageFailed=false;
try{const raw=localStorage.getItem(key);if(raw){const data=JSON.parse(raw);if(data.version!==1||!Array.isArray(data.entries))throw Error();entries=data.entries.map(validate);}}catch{storageFailed=true;}
$('#month').value=today().slice(0,7);
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,6000);}
function persist(next,force=false){if(storageFailed&&!force){toast('Restaure um backup antes de salvar: os dados antigos não puderam ser lidos.');return false;}try{localStorage.setItem(key,JSON.stringify({version:1,entries:next}));entries=next;storageFailed=false;render();return true;}catch{toast('Não foi possível salvar. Exporte um backup e confira o espaço do navegador.');return false;}}
const month=()=>$('#month').value;
const displayMonth=()=>new Date(month()+'-15T12:00:00').toLocaleDateString('pt-BR',{month:'long',year:'numeric'});
const dateText=s=>s.split('-').reverse().join('/');
function confirmAction(title,text,action){$('#confirm-title').textContent=title;$('#confirm-text').textContent=text;$('#confirm-ok').onclick=()=>{if(action()!==false)$('#confirm-dialog').close();};$('#confirm-dialog').showModal();}
$('#confirm-cancel').onclick=()=>$('#confirm-dialog').close();
const labels={overview:['Visão geral','Acompanhe o mês e decida seus próximos passos.'],entries:['Lançamentos','Cada entrada e saída, organizada em um só lugar.'],cash:['Fluxo de caixa','Entenda o que entrou, o que saiu e o que está previsto.'],dre:['DRE pessoal','O resultado do seu mês, pela competência de cada lançamento.'],excel:['Importar e exportar','Do seu Excel para o cofre. Do cofre para o seu Excel.']};
function navigate(p){page=p;document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));render();}
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page));
function card(label,value,note,cls='',icon='↗'){return `<article class="card ${cls}"><div class="label">${label}<span>${icon}</span></div><div class="metric">${money(value)}</div><small>${note}</small></article>`;}
function stats(){const s=summary(entries,month()),o=opening(entries,month());return `<div class="cards">${card('Saldo acumulado',o+s.result,'Até o fim do mês selecionado','balance','◈')}${card('Receitas recebidas',s.income,`${s.selected.filter(e=>e.type==='receita').length} entradas no mês`,'','↙')}${card('Despesas pagas',s.expense,`${s.selected.filter(e=>e.type==='despesa').length} saídas no mês`,'','↗')}${card('Resultado de caixa',s.result,s.income?`${(s.result/s.income*100).toFixed(1).replace('.',',')}% das receitas recebidas`:'Receitas menos despesas','','⌁')}</div>`;}
function empty(message='Comece a escrever sua história financeira.',action=true){return `<div class="empty"><div class="empty-icon">◈</div><h3>${message}</h3><p>Adicione um lançamento ou importe sua planilha.<br>Seus números aparecerão aqui.</p>${action?'<button class="primary" data-new>＋ Adicionar lançamento</button>':''}</div>`;}
function table(list,actions=true){return list.length?`<div class="table-wrap"><table><thead><tr><th>Descrição</th><th>Data</th><th>Categoria</th><th>Conta</th><th>Situação</th><th class="right">Valor</th>${actions?'<th class="right">Ações</th>':''}</tr></thead><tbody>${list.map(e=>`<tr><td><div class="desc"><span class="entry-icon ${e.type}">${e.type==='receita'?'↙':e.type==='despesa'?'↗':'⇄'}</span><div>${esc(e.description)}<small>Competência ${e.competence.split('-').reverse().join('/')}</small></div></div></td><td>${dateText(e.date)}</td><td>${esc(e.category)}</td><td>${esc(e.account)}${e.type==='transferencia'?`<small>→ ${esc(e.destination)}</small>`:''}</td><td><span class="badge ${e.status==='pendente'?'pending':''}">${e.status==='pago'?'Realizado':'Pendente'}</span></td><td class="right ${e.type==='receita'?'up':e.type==='despesa'?'down':''}">${e.type==='receita'?'+ ':e.type==='despesa'?'− ':''}${money(e.amount)}</td>${actions?`<td><div class="actions">${e.status==='pendente'?`<button data-pay="${esc(e.id)}">Dar baixa</button>`:''}<button data-edit="${esc(e.id)}">Editar</button><button data-delete="${esc(e.id)}" aria-label="Excluir ${esc(e.description)}">×</button></div></td>`:''}</tr>`).join('')}</tbody></table></div>`:empty('Nenhum lançamento neste período.');}
function chart(){const d=new Date(month()+'-15T12:00:00'),months=[];for(let i=5;i>=0;i--){const dt=new Date(d.getFullYear(),d.getMonth()-i,15),m=`${dt.getFullYear()}-${String(dt.getMonth()+1).padStart(2,'0')}`,s=summary(entries,m);months.push({...s,label:dt.toLocaleDateString('pt-BR',{month:'short'}).replace('.','')});}const max=Math.max(...months.flatMap(s=>[s.income,s.expense]),1);return `<div class="chart" role="img" aria-label="Receitas e despesas pagas nos últimos seis meses">${months.map(s=>`<div class="bar-group"><div class="bar" style="height:${s.income/max*100}%" title="Receitas ${s.label}: ${money(s.income)}"></div><div class="bar out" style="height:${s.expense/max*100}%" title="Despesas ${s.label}: ${money(s.expense)}"></div><span>${s.label}</span></div>`).join('')}</div><div class="chart-note">Realizado · últimos 6 meses até ${displayMonth()}</div>`;}
function categoryChart(){const s=summary(entries,month()),by={};s.selected.filter(e=>e.type==='despesa').forEach(e=>by[e.category]=(by[e.category]||0)+e.amount);return Object.keys(by).length?Object.entries(by).sort((a,b)=>b[1]-a[1]).slice(0,5).map(([k,v])=>`<div class="category-row"><div><span>${esc(k)}</span><span>${money(v)} <span class="muted">· ${Math.round(v/s.expense*100)}%</span></span></div><div class="track"><div style="width:${v/s.expense*100}%"></div></div></div>`).join(''):'<div class="empty"><div class="empty-icon">◌</div><p>Suas despesas por categoria<br>aparecerão aqui.</p></div>';}
function overview(){return stats()+`<div class="split"><section class="panel"><div class="panel-head"><div><h2>Seu dinheiro em movimento</h2><p>Um olhar sobre suas entradas e saídas.</p></div><div class="legend"><span><i></i>Receitas</span><span><i class="out"></i>Despesas</span></div></div>${chart()}</section><section class="panel"><div class="panel-head"><div><h2>Para onde foi seu dinheiro?</h2><p>Despesas pagas por categoria</p></div><span>↗</span></div>${categoryChart()}</section></div><section class="panel"><div class="panel-head"><div><h2>Últimos lançamentos</h2><p>Os movimentos mais recentes do mês.</p></div><button class="text-button" data-go="entries">Ver todos →</button></div>${table(entries.filter(e=>e.date.startsWith(month())).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5),false)}</section>`;}
function entriesView(){return `<section class="panel"><div class="filter-row"><input id="search" placeholder="Buscar lançamento…" aria-label="Buscar lançamento" value="${esc(search)}"><select id="type-filter" aria-label="Filtrar tipo"><option value="">Todos os tipos</option>${Object.keys(categories).map(t=>`<option value="${t}" ${typeFilter===t?'selected':''}>${({receita:'Receitas',despesa:'Despesas',transferencia:'Transferências'})[t]}</option>`).join('')}</select><select id="status-filter" aria-label="Filtrar situação"><option value="">Todas as situações</option><option value="pago" ${statusFilter==='pago'?'selected':''}>Realizados</option><option value="pendente" ${statusFilter==='pendente'?'selected':''}>Pendentes</option></select></div><div id="entries-table">${filteredTable()}</div></section>`;}
function filteredTable(){return table(entries.filter(e=>e.date.startsWith(month())&&e.description.toLocaleLowerCase('pt-BR').includes(search.toLocaleLowerCase('pt-BR'))&&(!typeFilter||e.type===typeFilter)&&(!statusFilter||e.status===statusFilter)).sort((a,b)=>b.date.localeCompare(a.date)));}
function cashView(){const s=summary(entries,month()),pending=entries.filter(e=>e.date.startsWith(month())&&e.status==='pendente'),projected=s.result+pending.reduce((v,e)=>v+sign(e)*e.amount,0),o=opening(entries,month());let running=o;const dates=[...new Set(entries.filter(e=>e.date.startsWith(month())&&e.status==='pago'&&e.type!=='transferencia').map(e=>e.date))].sort();return stats()+`<div class="notice">Saldo inicial: <strong>${money(o)}</strong> · Saldo previsto para o fim do mês: <strong>${money(o+projected)}</strong><br>A previsão soma os itens pendentes ao realizado. O saldo inicial acumula os registros pagos anteriores ao mês; registre também seus saldos de abertura.</div><section class="panel"><div class="panel-head"><h2>Caixa realizado por dia</h2><span class="muted">${displayMonth()}</span></div>${dates.length?`<div class="table-wrap"><table><thead><tr><th>Data</th><th class="right">Entradas</th><th class="right">Saídas</th><th class="right">Saldo acumulado</th></tr></thead><tbody>${dates.map(date=>{const rows=s.selected.filter(e=>e.date===date),inc=rows.filter(e=>e.type==='receita').reduce((v,e)=>v+e.amount,0),out=rows.filter(e=>e.type==='despesa').reduce((v,e)=>v+e.amount,0);running+=inc-out;return `<tr><td>${dateText(date)}</td><td class="right up">${money(inc)}</td><td class="right down">${money(out)}</td><td class="right">${money(running)}</td></tr>`;}).join('')}</tbody></table></div>`:empty('O caixa realizado ainda está vazio.')}</section><section class="panel" style="margin-top:22px"><div class="panel-head"><h2>A pagar e a receber</h2><span class="muted">${pending.length} pendentes</span></div>${pending.length?table(pending):'<p class="muted">Nenhum item pendente para este mês.</p>'}</section>`;}
function dreRows(){const s=summary(entries,month(),'competence',false);return [['Receitas pessoais',s.income],...categories.receita.map(c=>[c,s.selected.filter(e=>e.type==='receita'&&e.category===c).reduce((v,e)=>v+e.amount,0)]),['Despesas pessoais',-s.expense],...categories.despesa.map(c=>[c,-s.selected.filter(e=>e.type==='despesa'&&e.category===c).reduce((v,e)=>v+e.amount,0)]),['Resultado pessoal do mês',s.result]];}
function dreView(){const s=summary(entries,month(),'competence',false);return `<div class="notice">Relatório gerencial por competência · ${displayMonth()}. Inclui lançamentos pagos e pendentes. Transferências ficam fora do resultado. O fechamento exporta uma fotografia do mês; lançamentos continuam editáveis.</div><div class="cards">${card('Receitas da competência',s.income,'Pagas e pendentes')}${card('Despesas da competência',s.expense,'Pagas e pendentes')}${card('Resultado pessoal',s.result,'Receitas menos despesas','balance')}${card('Ainda a realizar',s.selected.filter(e=>e.status==='pendente').reduce((v,e)=>v+sign(e)*e.amount,0),'Saldo líquido de pendências')}</div><section class="panel"><div class="panel-head"><div><h2>Demonstração do resultado pessoal</h2><p>${displayMonth()} · BRL</p></div><button class="primary" data-export>↓ Fechar mês em Excel</button></div><div class="table-wrap"><table class="report"><thead><tr><th>Composição</th><th class="right">Valor</th></tr></thead><tbody>${dreRows().map(([label,value],i,rows)=>`<tr class="${i===rows.length-1?'final':label==='Receitas pessoais'||label==='Despesas pessoais'?'total':''}"><td>${esc(label)}</td><td class="right">${money(value)}</td></tr>`).join('')}</tbody></table></div></section><details class="panel" style="margin-top:22px"><summary>Conferir lançamentos da competência (${s.selected.length})</summary>${table(s.selected,false)}</details>`;}
function excelView(){return `<div class="notice">Use o modelo do Cofre para importar .xlsx, .xls ou .csv (até 5 MB e 10 mil linhas). Você confere os dados antes de confirmar; linhas idênticas são ignoradas para evitar duplicidade.</div><div class="excel-grid"><section class="panel"><span class="big-icon">↥</span><h2>Trazer sua planilha</h2><p>Baixe o modelo, preencha a aba Lançamentos e importe. Datas em AAAA-MM-DD, competência em AAAA-MM e valores positivos.</p><button id="template">↓ Baixar modelo Excel</button><div class="drop"><label>Selecione sua planilha<input class="file-input" id="import-file" type="file" accept=".xlsx,.xls,.csv"></label><span class="muted">Os dados só serão salvos após a confirmação.</span></div><div id="import-preview"></div></section><section class="panel"><span class="big-icon">↧</span><h2>Levar para o Excel</h2><p>Exporte o mês com DRE pessoal, fluxo de caixa e os lançamentos que compõem os relatórios, incluindo pagamentos de outras competências.</p><button class="primary" data-export>↓ Exportar ${displayMonth()}</button><h2 style="margin-top:38px">Guarde uma cópia completa</h2><p>O backup JSON contém todo o histórico. Use-o para recuperar seus registros ou levá-los a outro navegador.</p><button id="backup">↓ Baixar backup</button><label style="margin-top:20px">Restaurar backup JSON<input id="restore-file" class="file-input" type="file" accept=".json"></label></section></div>`;}
function render(){const [title,subtitle]=labels[page];$('#title').textContent=title;$('#subtitle').textContent=subtitle;$('#content').innerHTML=({overview,entries:entriesView,cash:cashView,dre:dreView,excel:excelView})[page]();bindContent();}
function bindContent(){document.querySelectorAll('[data-new]').forEach(b=>b.onclick=()=>openForm());document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>navigate(b.dataset.go));document.querySelectorAll('[data-export]').forEach(b=>b.onclick=()=>exportMonth());document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openForm(entries.find(e=>e.id===b.dataset.edit)));document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>confirmAction('Excluir lançamento?', 'O lançamento será removido dos relatórios. Guarde um backup se precisar manter uma cópia.',()=>persist(entries.filter(e=>e.id!==b.dataset.delete))));document.querySelectorAll('[data-pay]').forEach(b=>b.onclick=()=>openForm({...entries.find(e=>e.id===b.dataset.pay),status:'pago'}));
if($('#search'))$('#search').oninput=e=>{search=e.target.value;$('#entries-table').innerHTML=filteredTable();bindTable();};if($('#type-filter'))$('#type-filter').onchange=e=>{typeFilter=e.target.value;render();};if($('#status-filter'))$('#status-filter').onchange=e=>{statusFilter=e.target.value;render();};if($('#template'))$('#template').onclick=template;if($('#import-file'))$('#import-file').onchange=readImport;if($('#backup'))$('#backup').onclick=()=>download(JSON.stringify({version:1,entries},null,2),`cofre-gabriel-backup-${today()}.json`,'application/json');if($('#restore-file'))$('#restore-file').onchange=restore;}
function bindTable(){document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openForm(entries.find(e=>e.id===b.dataset.edit)));document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>confirmAction('Excluir lançamento?','O lançamento será removido dos relatórios.',()=>persist(entries.filter(e=>e.id!==b.dataset.delete))));document.querySelectorAll('[data-pay]').forEach(b=>b.onclick=()=>openForm({...entries.find(e=>e.id===b.dataset.pay),status:'pago'}));}
const form=$('#entry-form');function options(){const type=form.elements.type.value;form.elements.category.innerHTML=categories[type].map(c=>`<option>${c}</option>`).join('');$('#destination-label').hidden=type!=='transferencia';}
function openForm(e){form.reset();$('#form-error').textContent='';form.elements.id.value=e?.id||'';form.elements.type.value=e?.type||'despesa';options();form.elements.account.innerHTML=accounts.map(c=>`<option>${c}</option>`).join('');form.elements.destination.innerHTML=accounts.map(c=>`<option>${c}</option>`).join('');form.elements.destination.value=accounts[1];form.elements.date.value=today();form.elements.competence.value=month();if(e)for(const k of ['description','type','category','account','date','competence','status','destination'])if(e[k])form.elements[k].value=e[k];form.elements.amount.value=e?(e.amount/100).toFixed(2).replace('.',','):'';$('#form-title').textContent=e?'Editar lançamento':'Novo lançamento';$('#entry-dialog').showModal();form.elements.description.focus();}
form.elements.type.onchange=options;form.onsubmit=e=>{e.preventDefault();try{const v=Object.fromEntries(new FormData(form));v.id=v.id||crypto.randomUUID();v.description=v.description.trim();v.amount=cents(v.amount);if(v.type!=='transferencia')delete v.destination;validate(v);if(persist([...entries.filter(x=>x.id!==v.id),v])){$('#entry-dialog').close();toast('Lançamento salvo.');}}catch(error){$('#form-error').textContent=error.message;}};
$('#new-entry').onclick=()=>openForm();document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$('#entry-dialog').close());$('#month').onchange=()=>{if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(month()))$('#month').value=today().slice(0,7);render();};function shiftMonth(n){const d=new Date(month()+'-15T12:00:00');d.setMonth(d.getMonth()+n);$('#month').value=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;render();}$('#prev-month').onclick=()=>shiftMonth(-1);$('#next-month').onclick=()=>shiftMonth(1);$('#export-month').onclick=()=>exportMonth();
const headers=['ID','Data','Competencia','Descricao','Tipo','Categoria','Valor','Situacao','Conta','Destino'];
const exportRows=list=>list.map(e=>[e.id,e.date,e.competence,e.description,e.type,e.category,e.amount/100,e.status,e.account,e.destination||'']);
function sheet(rows,widths){const ws=XLSX.utils.aoa_to_sheet(rows);ws['!cols']=widths.map(w=>({wch:w}));return ws;}
function requireXlsx(){if(!globalThis.XLSX){toast('O componente Excel não carregou. Atualize a página.');return false;}return true;}
function exportMonth(){if(!requireXlsx())return;const wb=XLSX.utils.book_new(),s=summary(entries,month()),o=opening(entries,month());const report=sheet([['COFRE GABRIEL — DRE PESSOAL'],['Competência',month()],['Emitido em',today()],['Critério','Competência; pagos e pendentes; sem transferências'],[],['Composição','Valor (R$)'],...dreRows().map(([label,value])=>[label,value/100])],[42,62]);for(const [cell,v] of Object.entries(report))if(cell.startsWith('B')&&v.t==='n')v.z='"R$" #,##0.00';XLSX.utils.book_append_sheet(wb,report,'DRE pessoal');const cash=sheet([['FLUXO DE CAIXA',month()],['Saldo inicial',o/100],['Receitas recebidas',s.income/100],['Despesas pagas',s.expense/100],['Saldo final',(o+s.result)/100],['Observação','Saldo inicial calculado com todos os pagamentos anteriores.'],[],['Data','Descrição','Tipo','Conta','Valor (R$)'],...s.selected.map(e=>[e.date,e.description,e.type,e.account,sign(e)*e.amount/100])],[22,65,22,22,20]);for(const [cell,v] of Object.entries(cash))if(v.t==='n')v.z='"R$" #,##0.00';XLSX.utils.book_append_sheet(wb,cash,'Fluxo de caixa');const list=entries.filter(e=>e.date.startsWith(month())||e.competence===month());const detail=sheet([headers,...exportRows(list)],[38,14,14,40,18,25,18,16,22,22]);for(const [cell,v] of Object.entries(detail))if(cell.startsWith('G')&&v.t==='n')v.z='"R$" #,##0.00';XLSX.utils.book_append_sheet(wb,detail,'Lançamentos');XLSX.writeFile(wb,`Cofre-Gabriel-${month()}.xlsx`);toast('Relatório mensal exportado.');}
function template(){if(!requireXlsx())return;const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,sheet([headers],[38,14,14,40,18,25,18,16,22,22]),'Lançamentos');const guide=[['COMO PREENCHER'],['ID','Opcional. Deixe vazio para novos lançamentos.'],['Data','AAAA-MM-DD. Data do pagamento ou previsão.'],['Competencia','AAAA-MM. Mês do resultado pessoal.'],['Descricao','Descrição obrigatória.'],['Tipo','receita, despesa ou transferencia'],['Valor','Número positivo em reais. Ex.: 150,90'],['Situacao','pago ou pendente'],['Conta',accounts.join(', ')],['Destino','Somente transferências. Deve ser diferente da conta.'],['Categoria','Use uma categoria compatível abaixo.'],...Object.entries(categories).map(([k,v])=>[k,v.join(', ')])];XLSX.utils.book_append_sheet(wb,sheet(guide,[24,110]),'Instruções');XLSX.writeFile(wb,'Modelo-Cofre-Gabriel.xlsx');}
function parseDate(value){if(typeof value==='number'){const p=XLSX.SSF.parse_date_code(value);if(!p)throw Error('Data Excel inválida');return `${p.y}-${String(p.m).padStart(2,'0')}-${String(p.d).padStart(2,'0')}`;}const s=String(value??'').trim();if(/^\d{2}\/\d{2}\/\d{4}$/.test(s))return s.split('/').reverse().join('-');return s;}
async function readImport(event){const file=event.target.files[0];if(!file)return;pendingImport=null;const preview=$('#import-preview');preview.textContent='Lendo planilha…';try{if(!requireXlsx())return;if(file.size>5*1024*1024)throw Error('O limite é de 5 MB.');const wb=XLSX.read(await file.arrayBuffer(),{type:'array'});const name=wb.SheetNames.find(n=>['lancamentos','lançamentos'].includes(n.toLowerCase()))||wb.SheetNames[0],rows=XLSX.utils.sheet_to_json(wb.Sheets[name],{defval:''});if(rows.length>10000)throw Error('O limite é de 10 mil linhas.');if(!rows.length)throw Error('A planilha não contém lançamentos.');const errors=[],incoming=[];rows.forEach((row,i)=>{try{const norm=Object.fromEntries(Object.entries(row).map(([k,v])=>[k.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim(),v]));const e={id:String(norm.id||crypto.randomUUID()),date:parseDate(norm.data),competence:String(norm.competencia||''),description:String(norm.descricao||'').trim(),type:String(norm.tipo||'').toLowerCase().trim(),category:String(norm.categoria||'').trim(),amount:cents(norm.valor),status:String(norm.situacao||'').toLowerCase().trim(),account:String(norm.conta||'').trim()};if(e.type==='transferencia')e.destination=String(norm.destino||'').trim();incoming.push(validate(e));}catch(e){errors.push(`Linha ${i+2}: ${e.message}`);}});if(errors.length){preview.innerHTML=`<p class="down">Importação bloqueada. Corrija ${errors.length} linha(s).</p><div class="preview-list">${errors.slice(0,20).map(esc).join('<br>')}</div>`;return;}const result=mergeImport(entries,incoming);pendingImport=incoming;preview.innerHTML=`<p>${result.added} novos lançamentos · ${result.duplicates} duplicados ignorados.</p><div class="preview-list">${incoming.slice(0,8).map(e=>`${esc(e.description)} · ${dateText(e.date)} · ${money(e.amount)}`).join('<br>')}</div><button class="primary" id="confirm-import" ${result.added?'':'disabled'}>Confirmar importação</button>`;$('#confirm-import').onclick=()=>{try{const current=mergeImport(entries,pendingImport);if(persist(current.entries)){pendingImport=null;toast(`${current.added} lançamentos importados.`);}}catch(e){toast(e.message);}};}catch(e){preview.textContent='Não foi possível importar: '+e.message;}}
function download(content,name,type){const u=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
async function restore(event){const file=event.target.files[0];if(!file)return;try{if(file.size>10*1024*1024)throw Error('Backup excede 10 MB.');const data=JSON.parse(await file.text());if(data.version!==1||!Array.isArray(data.entries))throw Error('Formato de backup inválido.');const next=data.entries.map(validate);const ids=new Set();for(const e of next){if(typeof e.id!=='string'||!e.id||ids.has(e.id))throw Error('IDs inválidos ou repetidos no backup.');ids.add(e.id);}confirmAction('Substituir o histórico?',`Este backup contém ${next.length} lançamentos e substituirá os ${entries.length} registros atuais. Baixe um backup atual antes de continuar se precisar preservá-los.`,()=>{if(persist(next,true)){toast('Backup restaurado.');return true;}return false;});}catch(e){toast(e.message);}}
render();if(storageFailed)toast('Os dados salvos não puderam ser lidos. Não foram sobrescritos. Restaure um backup antes de adicionar registros.');
